def transform(grid):
    """Translate the foreground pattern one row downward; preserve background."""
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        out[r + 1] = list(grid[r])
    return out

if __name__ == '__main__':
    demo = [[8]*21 for _ in range(8)]
    marks = {
        0:[12], 1:[8,10,11], 2:[9,10,11,12], 3:[8,12,13,14],
        4:[6,7,10,11,13,14], 5:[10,11,12], 6:[12,13,15], 7:[14,15]
    }
    for r, cols in marks.items():
        for c in cols: demo[r][c] = 5
    out = transform(demo)
    expected = [[8]*21] + demo[:-1]
    assert out == expected
    print('complete demo pair exact match')", "exit_code": 0, "error": null}

